const data = input.body || input;

const allInputs = $input.all();
console.log('✅ Agent 5: Received', allInputs.length, 'item(s)');

if (allInputs.length !== 1) {
  console.error('⚠️ AGENT 5 ERROR: Expected 1 item, got', allInputs.length);
}

