const data = $input.first().json;
const finalPost = data.finalPost || '';
const wordCount = data.wordCount || 0;
const sectionCount = data.sectionCount || 0;

// Validation checks
const issues = [];
const hasTitle = /^#\s+/.test(finalPost);

if (wordCount < 2500) {
  issues.push({type: 'word_count_low', severity: 'high', message: `Word count ${wordCount} below target 2500`});
}

if (!hasTitle) {
  issues.push({type: 'missing_title', severity: 'critical', message: 'Blog post missing H1 title'});
}

if (sectionCount < 3) {
  issues.push({type: 'insufficient_sections', severity: 'medium', message: `Only ${sectionCount} sections, expected 6+`});
}

if (finalPost.length < 500) {
  issues.push({type: 'content_too_short', severity: 'critical', message: 'Post content is critically short'});
}

// Check for first-person language (common issue)
const firstPersonWords = ['I am', 'I have', 'I will', 'my ', 'we are', 'we have', 'our ', 'I\'ve', 'I\'m'];
const hasFirstPerson = firstPersonWords.some(word => finalPost.toLowerCase().includes(word.toLowerCase()));
if (hasFirstPerson) {
  issues.push({type: 'first_person_language', severity: 'medium', message: 'Detected first-person perspective'});
}

// Calculate quality score based on issues
let qualityScore = 10;
if (wordCount < 2500) qualityScore -= 2;
if (!hasTitle) qualityScore -= 3;
if (sectionCount < 3) qualityScore -= 1;
if (hasFirstPerson) qualityScore -= 1;
if (finalPost.length < 500) qualityScore -= 5;

qualityScore = Math.max(0, qualityScore);

console.log('📊 Agent 5: Quality validation - Score:', qualityScore, 'Issues:', issues.length);

const timestamp = new Date().toISOString();

return [{
  json: {
    finalPost: finalPost,
    sources: data.sources || [],
    topic: data.topic,
    style: data.style,
    length: data.length,
    wordCount: wordCount,
    sectionCount: sectionCount,
    quality_score: qualityScore,
    word_count: wordCount,
    section_count: sectionCount,
    retry_count: 0,
    timestamp: timestamp,
    issues: issues,
    hasIssues: issues.length > 0
  }
}];

const data = $input.first().json;

if (!data.hasIssues) {
