const data = $input.first().json;
const timestamp = new Date().toISOString();
const sources = data.sources || [];

if (!Array.isArray(sources) || sources.length === 0) {
  return [];
}

const sourceRecords = [];

sources.forEach(source => {
  try {
    const urlString = source.url || source;
    // Manual URL parsing since URL constructor isn't available
    // Extract domain from https://domain.com/path format
    const match = urlString.match(/^https?:\/\/([^\/]+)/);
    if (match && match[1]) {
      const domain = match[1];
      sourceRecords.push({
        json: {
          domain: domain,
          quality_score: 8,
          timestamp: timestamp
        }
      });
    }
  } catch (e) {
    // Silently skip failed parses
  }
});

if (sourceRecords.length === 0) {
  return [];
}

return sourceRecords;

const data = $input.first().json;
const markdown = data.finalPost || '';

// Simple but reliable markdown to HTML converter
function markdownToHtml(md) {
  let html = md;

  // Code blocks (must be before inline code)
  html = html.replace(/```([a-z]*)\n([\s\S]*?)```/g, '<pre><code class="language-$1">$2</code></pre>');

  // Headings
  html = html.replace(/^#### (.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');

  // Bold
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');

  // Italic
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
  html = html.replace(/_(.+?)_/g, '<em>$1</em>');

  // Links
  html = html.replace(/\[([^\]]+)\]\(([^\)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Horizontal rules
  html = html.replace(/^---$/gm, '<hr>');
  html = html.replace(/^\*\*\*$/gm, '<hr>');

  // Unordered lists
  html = html.replace(/^[\*\-] (.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>');

  // Blockquotes
  html = html.replace(/^> (.+)$/gm, '<blockquote>$1</blockquote>');

  // Tables (basic support)
  html = html.replace(/\|(.+)\|/g, (match) => {
    const cells = match.split('|').filter(c => c.trim()).map(c => `<td>${c.trim()}</td>`).join('');
    return `<tr>${cells}</tr>`;
  });
  html = html.replace(/(<tr>.*<\/tr>)/s, '<table>$1</table>');

  // Paragraphs (wrap text not in tags)
  const lines = html.split('\n');
  const processed = [];
  let inParagraph = false;

  for (let line of lines) {
    line = line.trim();
    if (!line) {
      if (inParagraph) {
        processed.push('</p>');
        inParagraph = false;
      }
      continue;
    }

    // Skip if already wrapped in a tag
    if (line.startsWith('<')) {
      if (inParagraph) {
        processed.push('</p>');
        inParagraph = false;
      }
      processed.push(line);
    } else {
      if (!inParagraph) {
        processed.push('<p>');
        inParagraph = true;
      }
      processed.push(line + ' ');
    }
  }
  if (inParagraph) processed.push('</p>');

  return processed.join('\n');
}

const htmlContent = markdownToHtml(markdown);

// Extract title from HTML content (first h1)
let title = 'Untitled Post';
const h1Match = htmlContent.match(/<h1>([^<]+)<\/h1>/);
if (h1Match) {
  title = h1Match[1].trim();
}

// Generate slug from title
const slug = title.toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

// Get today's date in YYYY-MM-DD format
const today = new Date().toISOString().split('T')[0];

// Estimate reading time (words per minute = 200)
const readingTime = Math.ceil(data.wordCount / 200);

// Generate meta description from first paragraph (150-160 chars for SEO)
let metaDescription = '';
const firstPMatch = htmlContent.match(/<p>([^<]+)<\/p>/);
if (firstPMatch) {
  const firstParagraph = firstPMatch[1].trim();
  if (firstParagraph.length <= 160) {
    metaDescription = firstParagraph;
  } else {
    // Truncate to ~155 chars at word boundary
    metaDescription = firstParagraph.substring(0, 155);
    const lastSpace = metaDescription.lastIndexOf(' ');
    if (lastSpace > 130) {
      metaDescription = metaDescription.substring(0, lastSpace) + '...';
    } else {
      metaDescription = metaDescription + '...';
    }
  }
}

// Extract keywords from topic and title (common SEO keywords)
const keywords = [];
const topicLower = (data.topic || '').toLowerCase();
const titleLower = title.toLowerCase();

// Common tech/AI keywords
const commonKeywords = [
  'ai', 'artificial intelligence', 'machine learning', 'ml', 'deep learning',
  'neural network', 'llm', 'gpt', 'chatbot', 'automation', 'robotics',
  'data science', 'python', 'javascript', 'typescript', 'react', 'node',
  'cloud', 'aws', 'azure', 'kubernetes', 'docker', 'api', 'blockchain',
  'crypto', 'web3', 'devops', 'security', 'privacy', 'quantum', 'startup',
  'tech', 'software', 'programming', 'developer', 'code', 'open source'
];

// Extract keywords that appear in topic or title
commonKeywords.forEach(kw => {
  if (topicLower.includes(kw) || titleLower.includes(kw)) {
    keywords.push(kw);
  }
});

// Add current year as keyword
keywords.push('2026');

// Limit to top 8-10 keywords
const finalKeywords = keywords.slice(0, 10);

const timestamp = new Date().toISOString();

return [{
  json: {
    slug: slug,
    title: title,
    date: today,
    excerpt: metaDescription,
    metaDescription: metaDescription,
    keywords: finalKeywords,
    tags: ['AI', 'Machine Learning', '2026'],
    readingTime: readingTime,
    content: htmlContent,
    sources: data.sources || [],
    wordCount: data.wordCount,
    qualityScore: data.quality_score,
    editorNotes: {
      topic: data.topic,
      style: data.style,
      length: data.length,
      wordCount: data.wordCount,
      sectionCount: data.sectionCount,
      generatedAt: timestamp
    }
  }
}];

// Get post data from the prep node, not the API response
const postData = $("Convert MD to HTML & Prep Payload").first().json;

// Hardcoded notification chat ID
const NOTIFICATION_CHAT_ID = '551663660';

const title = postData.title || 'Untitled Post';
const slug = postData.slug || '';
const metaDescription = postData.metaDescription || postData.excerpt || '';
const wordCount = postData.wordCount || 0;
const qualityScore = postData.qualityScore || 0;
const readingTime = postData.readingTime || 0;

const message = `📝 *NEW POST PUBLISHED*\n\n*Title:* ${title}\n\n*Excerpt:* ${metaDescription.substring(0, 150)}${metaDescription.length > 150 ? '...' : ''}\n\n*Stats:*\n• Words: ${wordCount}\n• Quality: ${qualityScore}/10\n• Reading time: ${readingTime} min\n\n🔗 https://mabus.ai/blog/${slug}`;

console.log('📱 Agent 5: Sending Telegram notification for:', title);

return [{
  json: {
    chatId: NOTIFICATION_CHAT_ID,
    message: message,
    title: title,
    slug: slug
  }
}];

